<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import { adminDelete, adminGet, adminPost, adminPut } from "../../../admin/api/adminClient";
import { teacherDelete, teacherGet, teacherPost } from "../../../teacher/teacherApi";
import { adminPath } from "../../../utils/adminPath";
import { encryptId } from "../../../utils/cipher";
import HtmlMath from "../../components/HtmlMath.vue";
import CodeEditor from "../../components/CodeEditor.vue";
import { formatDisplayDateTime } from "../../../lib/format";

type Problem={id:number;title:string;statement?:string;inputFormat?:string;outputFormat?:string;difficulty:number;tags:string[];folderId?:number;folderName?:string;ownerName?:string;acRate:number;isPublic:boolean;createdAt:string;timeLimit?:number;memoryLimit?:number;testCaseCount:number;accessScope:string;majorName?:string;studentPublishStatus:"DRAFT"|"PUBLISHED";canEdit:boolean;samples?:Array<{input:string;output:string;explanation?:string}>};
type Folder={id:number;name:string};type Page<T>={list:T[];total:number};type Solution={level:number;content:string;source:"AI"|"MANUAL"};
const route=useRoute();const router=useRouter();const teacherMode=computed(()=>route.path.startsWith("/teacher/"));
function get<T>(url:string){return teacherMode.value?teacherGet<T>(url):adminGet<T>(url);}function post<T>(url:string,body?:unknown){return teacherMode.value?teacherPost<T>(url,body):adminPost<T>(url,body);}function remove<T>(url:string){return teacherMode.value?teacherDelete<T>(url):adminDelete<T>(url);}
const loading=ref(false);const error=ref("");const rows=ref<Problem[]>([]);const total=ref(0);const folders=ref<Folder[]>([]);const selected=ref<Problem[]>([]);const page=ref(1);const pageSize=ref(20);const filters=reactive({keyword:"",difficulty:"",tag:"",folderId:"",ownerName:""});
const previewVisible=ref(false);const previewLoading=ref(false);const preview=ref<Problem|null>(null);const solutionVisible=ref(false);const solutionProblem=ref<Problem|null>(null);const solutionLoading=ref(false);const solutionSaving=ref(false);const solutionGenerating=ref(false);const height=ref(0);const solutions=ref<Solution[]>([]);const batchVisible=ref(false);const batchAction=ref<"publish"|"unpublish"|"delete">("publish");const batchBusy=ref(false);
const selectedEditable=computed(()=>selected.value.filter(item=>item.canEdit));const unpublished=computed(()=>selectedEditable.value.filter(item=>item.studentPublishStatus!=="PUBLISHED"));const published=computed(()=>selectedEditable.value.filter(item=>item.studentPublishStatus==="PUBLISHED"));const batchIds=computed(()=>batchAction.value==="publish"?unpublished.value.map(item=>item.id):batchAction.value==="unpublish"?published.value.map(item=>item.id):selectedEditable.value.map(item=>item.id));
const params=computed(()=>{const p=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value)});if(filters.keyword.trim())p.set("keyword",filters.keyword.trim());if(filters.difficulty)p.set("difficulty",filters.difficulty);if(filters.tag.trim())p.set("tag",filters.tag.trim());if(filters.folderId)p.set("folderId",filters.folderId);if(filters.ownerName.trim())p.set("ownerName",filters.ownerName.trim());return p.toString();});
async function load(){loading.value=true;error.value="";try{const result=await get<Page<Problem>>(`/api/admin/v1/problems?${params.value}`);rows.value=result.list??[];total.value=result.total??0;selected.value=selected.value.filter(item=>result.list.some(row=>row.id===item.id&&row.canEdit));}catch(cause){error.value=cause instanceof Error?cause.message:"题目列表加载失败";}finally{loading.value=false;}}
async function loadFolders(){try{folders.value=await get<Folder[]>("/api/admin/v1/problem-folders");}catch{folders.value=[];}}
function edit(item:Problem,segment="edit"){void router.push(teacherMode.value?`/teacher/problems/${encryptId(item.id)}/${segment}`:adminPath(`/problems/${encryptId(item.id)}/${segment}`));}
async function openPreview(item:Problem){previewVisible.value=true;previewLoading.value=true;try{preview.value=await get<Problem>(`/api/admin/v1/problems/${item.id}`);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"题目详情加载失败");preview.value=item;}finally{previewLoading.value=false;}}
async function deleteProblem(item:Problem){try{await ElMessageBox.confirm(`确定删除题目“${item.title}”吗？`,"删除题目",{type:"warning"});await remove(`/api/admin/v1/problems/${item.id}`);ElMessage.success("题目已删除");await load();}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"删除失败");}}
async function runBatch(){if(!batchIds.value.length){ElMessage.warning("所选题目没有可执行的操作");return;}batchBusy.value=true;try{const result=await post<number>(`/api/admin/v1/problems/batch-${batchAction.value}`,{ids:batchIds.value});ElMessage.success(`已${{publish:"发布",unpublish:"下架",delete:"删除"}[batchAction.value]} ${Number(result)||batchIds.value.length} 道题目`);batchVisible.value=false;selected.value=[];await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"批量操作失败");}finally{batchBusy.value=false;}}
function openSolutions(item:Problem){solutionProblem.value=item;solutionVisible.value=true;height.value=0;solutions.value=[];void loadSolutions(item.id);}
async function loadSolutions(id:number){solutionLoading.value=true;try{const value=await get<{height:number;levels:Array<{level:number;content:string;source:string}>}>(`/api/admin/v1/problems/${id}/solutions`);height.value=value.height;solutions.value=value.levels.map(row=>({level:row.level,content:row.content??"",source:row.source==="AI"?"AI":"MANUAL"}));}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"题解加载失败");}finally{solutionLoading.value=false;}}
function changeHeight(value:number|undefined){height.value=Math.max(0,Math.min(12,Math.trunc(Number(value)||0)));solutions.value=Array.from({length:height.value},(_,index)=>solutions.value[index]??({level:index+1,content:"",source:"MANUAL"}));}
async function generateSolutions(){if(!solutionProblem.value||height.value<1)return;solutionGenerating.value=true;try{const contents=await adminPost<string[]>(`/api/admin/v1/problems/${solutionProblem.value.id}/solutions/generate`,{height:height.value},true,180000);if(!Array.isArray(contents)||contents.length!==height.value||contents.some(text=>Array.from(text).length>200))throw new Error("AI 返回层数无效，或单层超过 200 字");solutions.value=contents.map((content,index)=>({level:index+1,content,source:"AI"}));ElMessage.success(`已生成 ${height.value} 层题解`);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"AI 生成失败");}finally{solutionGenerating.value=false;}}
async function saveSolutions(){if(!solutionProblem.value||height.value<1){ElMessage.warning("请设置 1 到 12 层题解");return;}if(solutions.value.some(item=>Array.from(item.content).length>200)){ElMessage.warning("每层题解不能超过 200 字");return;}solutionSaving.value=true;try{await adminPut(`/api/admin/v1/problems/${solutionProblem.value.id}/solutions`,{height:height.value,levels:solutions.value});ElMessage.success("题解已保存");solutionVisible.value=false;}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"题解保存失败");}finally{solutionSaving.value=false;}}
watch(()=>[route.fullPath,page.value,pageSize.value,filters.keyword,filters.difficulty,filters.tag,filters.folderId,filters.ownerName] as const,()=>{void load();},{immediate:true});watch(()=>route.fullPath,()=>{void loadFolders();},{immediate:true});
</script>

<template><section class="problem-management page-container"><el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><template #default><el-button link type="primary" @click="load">重试</el-button></template></el-alert>
  <el-card shadow="never"><div class="filter-row management-inline-toolbar"><el-input v-model="filters.keyword" clearable placeholder="题目名称" @keyup.enter="page=1;load()"/><el-select v-model="filters.difficulty" clearable placeholder="难度"><el-option label="入门" value="1"/><el-option label="简单" value="2"/><el-option label="中等" value="3"/><el-option label="困难" value="4"/><el-option label="地狱" value="5"/></el-select><el-input v-model="filters.tag" clearable placeholder="知识点"/><el-select v-model="filters.folderId" clearable filterable placeholder="文件夹"><el-option v-for="item in folders" :key="item.id" :value="String(item.id)" :label="item.name"/></el-select><el-input v-model="filters.ownerName" clearable placeholder="创建者"/><el-button @click="page=1;load()">搜索</el-button><div class="management-card-actions"><header class="page-heading"><div class="actions"><el-button type="primary" @click="router.push(teacherMode?'/teacher/problems/new':adminPath('/problems/new'))">新增题目</el-button></div></header></div></div><div class="selection-row"><span>本页已选 {{selectedEditable.length}} 道可管理题目</span><div><el-button :disabled="!selectedEditable.length||loading" @click="batchVisible=true;batchAction=unpublished.length?'publish':'unpublish'">批量管理</el-button><el-button :disabled="!selected.length" @click="selected=[]">取消选择</el-button></div></div>
    <el-table v-loading="loading" :data="rows" stripe row-key="id" @selection-change="selected=$event"><el-table-column align="center" header-align="center" type="selection" width="48" :selectable="(row:Problem)=>row.canEdit"/><el-table-column align="center" header-align="center" prop="title" label="题目名称" min-width="140"/><el-table-column align="center" header-align="center" prop="ownerName" label="创建者" min-width="140"><template #default="{row}">{{row.ownerName||'-'}}</template></el-table-column><el-table-column align="center" header-align="center" label="难度" min-width="140"><template #default="{row}"><el-tag>{{({1:'入门',2:'简单',3:'中等',4:'困难',5:'地狱'} as Record<number,string>)[row.difficulty]||'未知'}}</el-tag></template></el-table-column><el-table-column align="center" header-align="center" prop="folderName" label="文件夹" min-width="140"><template #default="{row}">{{row.folderName||'-'}}</template></el-table-column><el-table-column align="center" header-align="center" label="学生题库" min-width="140"><template #default="{row}"><el-tag :type="row.studentPublishStatus==='PUBLISHED'?'success':'info'">{{row.studentPublishStatus==='PUBLISHED'?'已发布':'未发布'}}</el-tag></template></el-table-column><el-table-column align="center" header-align="center" label="操作" min-width="310" fixed="right"><template #default="{row}"><el-button link @click="openPreview(row)">查看</el-button><el-button link type="primary" :disabled="!row.canEdit" @click="edit(row)">编辑</el-button><el-button link :disabled="!row.canEdit" @click="edit(row,'test-cases')">测试点</el-button><el-button v-if="!teacherMode" link @click="openSolutions(row)">题解</el-button><el-button link type="danger" :disabled="!row.canEdit" @click="deleteProblem(row)">删除</el-button></template></el-table-column></el-table><div class="pagination"><Pagination v-model:page="page" v-model:limit="pageSize" :page-sizes="[10,20,50]" :total="total"/></div></el-card>
  
<el-dialog class="qoj-management-dialog" v-model="previewVisible" :title="preview?`题目预览 · ${preview.title}`:'题目预览'" width="min(1000px,94vw)"><el-skeleton v-if="previewLoading" :rows="8" animated/><template v-else-if="preview"><div class="preview-meta"><el-tag>#{{preview.id}}</el-tag><el-tag>{{({1:'入门',2:'简单',3:'中等',4:'困难',5:'地狱'} as Record<number,string>)[preview.difficulty]||'未知'}}</el-tag><el-tag v-for="tag in preview.tags??[]" :key="tag">{{tag}}</el-tag><span>{{preview.timeLimit}} ms · {{preview.memoryLimit}} MB · {{preview.testCaseCount}} 个测试点</span></div><h2>{{preview.title}}</h2><HtmlMath :value="preview.statement"/><el-descriptions :column="2" border><el-descriptions-item label="输入格式"><HtmlMath :value="preview.inputFormat"/></el-descriptions-item><el-descriptions-item label="输出格式"><HtmlMath :value="preview.outputFormat"/></el-descriptions-item></el-descriptions><el-divider content-position="left">样例</el-divider><div v-for="(sample,index) in preview.samples??[]" :key="index" class="sample"><strong>样例 {{index+1}}</strong><div class="sample-grid"><HtmlMath :value="sample.input" class-name="sample-value" :preserve-plain-text-whitespace="true"/><HtmlMath :value="sample.output" class-name="sample-value" :preserve-plain-text-whitespace="true"/></div><HtmlMath v-if="sample.explanation" :value="sample.explanation" class-name="sample-explanation"/></div></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="batchVisible" title="批量管理题目" width="560px"><p>所选 {{selectedEditable.length}} 道题目，可选择发布、下架或删除。</p><el-radio-group v-model="batchAction"><el-radio-button value="publish">发布（{{unpublished.length}}）</el-radio-button><el-radio-button value="unpublish">下架（{{published.length}}）</el-radio-button><el-radio-button value="delete">删除（{{selectedEditable.length}}）</el-radio-button></el-radio-group><el-alert v-if="batchAction==='delete'" type="warning" :closable="false" title="删除后题目将从题库移除，请确认所选内容。"/><template #footer><el-button @click="batchVisible=false">取消</el-button><el-button type="primary" :loading="batchBusy" :disabled="!batchIds.length" @click="runBatch">确认操作</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="solutionVisible" :title="`题解设置${solutionProblem?`：${solutionProblem.title}`:''}`" width="min(1100px,94vw)"><div class="solution-tools"><strong>题解树高度</strong><el-input-number :model-value="height" :min="0" :max="12" @update:model-value="changeHeight"/><el-button type="primary" :loading="solutionGenerating" :disabled="solutionLoading||solutionSaving||height<1" @click="generateSolutions">AI 一键生成全部层</el-button><span class="muted">每层最多 200 字，支持 $...$ 和 $$...$$；保存后会重置学生题解进度。</span></div><el-skeleton v-if="solutionLoading" :rows="6" animated/><el-card v-for="item in solutions" :key="item.level" shadow="never" class="solution-card"><template #header><strong>第 {{item.level}} 层 · {{item.source==='AI'?'AI 生成':'人工编辑'}}</strong></template><el-input v-model="item.content" type="textarea" :rows="4" maxlength="200" show-word-limit :disabled="solutionGenerating" @input="item.source='MANUAL'"/></el-card><el-empty v-if="!solutionLoading&&!solutions.length" description="设置高度后逐层编辑或生成题解"/><template #footer><el-button @click="solutionVisible=false">取消</el-button><el-button type="primary" :loading="solutionSaving" :disabled="solutionLoading||solutionGenerating" @click="saveSolutions">保存题解</el-button></template></el-dialog>
</section></template>

<style scoped>.problem-management{display:flex;flex-direction:column;gap:16px}.page-heading,.actions,.filter-row,.selection-row,.pagination,.solution-tools,.preview-meta{display:flex;align-items:center;gap:9px}.page-heading,.selection-row,.pagination{justify-content:space-between}.page-heading h1{margin:0;font-size:22px}.page-heading p,.muted{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.filter-row{flex-wrap:wrap;margin-bottom:15px}.filter-row>*{width:145px}.filter-row>.el-input:first-child{width:180px}.selection-row{margin-bottom:10px;color:var(--el-text-color-secondary);font-size:13px}.pagination{margin-top:14px}.preview-meta{flex-wrap:wrap;color:var(--el-text-color-secondary);font-size:13px}.sample{margin:12px 0;padding:12px;border:1px solid #ebeef5;border-radius:8px}.sample-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.sample-grid :deep(.sample-value){min-width:0;overflow:auto;margin:8px 0 0;padding:10px;background:var(--el-fill-color-light)}.sample :deep(.sample-explanation){margin-top:10px}.solution-tools{flex-wrap:wrap;margin-bottom:16px}.solution-card{margin-bottom:12px}.solution-card :deep(.el-card__header){padding:9px 14px}@media(max-width:700px){.page-heading,.selection-row,.pagination{align-items:flex-start;flex-direction:column}.sample-grid{grid-template-columns:1fr}}</style>
